WITH sequenced AS (SELECT mktcode,tgtcode,bizdate,volume,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS seq FROM `newzl`.`hsj_stock_hq_basic`), candidates AS (SELECT mktcode,tgtcode FROM sequenced WHERE seq<=3 GROUP BY mktcode,tgtcode HAVING COUNT(*)>0 AND SUM(CASE WHEN volume>0 THEN 1 ELSE 0 END)=COUNT(*)), period_metric AS (SELECT mktcode,tgtcode,MAX_BY(turnover,bizdate) AS value FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' WEEK) AND bizdate<=DATE_SUB(DATE_TRUNC((SELECT MAX(bizdate) FROM `newzl`.`hsj_stock_hq_basic`), 'WEEK'), INTERVAL '1' DAY) GROUP BY mktcode,tgtcode), joined AS (SELECT c.mktcode,c.tgtcode,'2026-04-14' AS bizdate,p.value FROM candidates c JOIN period_metric p ON p.mktcode=c.mktcode AND p.tgtcode=c.tgtcode), ranked AS (SELECT mktcode,tgtcode,bizdate,ROW_NUMBER() OVER(ORDER BY CASE WHEN value IS NULL THEN 1 ELSE 0 END,value ASC,mktcode,tgtcode) AS rn,COUNT(*) OVER() AS population FROM joined) SELECT mktcode,tgtcode,bizdate FROM ranked WHERE rn<CEIL(population*5/100.0);
